// Function to sanitize input by removing newline and carriage return characters
void sanitize_input(char *input) {
    char *src = input, *dst = input;
    while (*src) {
        if (*src != '\n' && *src != '\r') {
            *dst++ = *src;
        }
        src++;
    }
    *dst = '\0';
}

