char *get_user(sqlite3 *db, const char *username, const char *password) {
    sqlite3_stmt *stmt;
    char query[256];
    char *userInfo = NULL;

    snprintf(query, sizeof(query), "SELECT userInfo FROM users WHERE username = '%s' AND password = '%s'", username, password);

