    xpath_obj = xmlXPathEvalExpression((xmlChar*)xpath_query, xpath_ctx);
    if(xpath_obj == NULL) {
        fprintf(stderr, "Failed to evaluate XPath expression\n");
        xmlXPathFreeContext(xpath_ctx);
        xmlFreeDoc(doc);
        return NULL;
    }

