            if (get_next_file((int)imageno, dirptr, &img_fol, &parameters)) {
                fprintf(stderr, "skipping file...\n");
                continue;
            }
        }

        switch (parameters.decod_format) {
        case PGX_DFMT:
        case PXM_DFMT:
        case BMP_DFMT:
        case TIF_DFMT:
        case RAW_DFMT:
        case RAWL_DFMT:
        case TGA_DFMT:
        case PNG_DFMT:
