            if (TLM) {
                options[iOpt++] = "TLM=YES";
            }
            (void)iOpt;
            if (!opj_encoder_set_extra_options(l_codec, options)) {
                fprintf(stderr, "failed to encode image: opj_encoder_set_extra_options\n");
