                memcpy(dest, "&quot;", 6);
                dest += 6;
                break;
            case '\'':
                memcpy(dest, "&#x27;", 6);
                dest += 6;
                break;
            default:
                *dest = *ptr;
                dest += 1;
                break;
        }
        ptr++;
    }

    *dest = '\0'; // Null-terminate the string
